from pathlib import Path
import json
root=Path(__file__).resolve().parent; out=root/'research/outputs/sapa_wellbeing_terrain_explorer'; data=json.loads((out/'wellbeing_surface_bundle.json').read_text())
html='''<!doctype html><html><head><meta charset="utf-8"><title>SAPA Wellbeing Terrain</title><script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script><style>body{font-family:system-ui;margin:20px;color:#18202a}.note{background:#eef5f7;padding:10px;border-left:4px solid #2b7280}.grid{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.panel{border:1px solid #d9e0e5;padding:10px;margin:8px 0}label{margin-right:10px}.slider{display:block}.small{font-size:12px;color:#50606d}#plot{height:640px}#status{font-weight:600}</style></head><body><h1>SAPA Human Wellbeing Terrain Explorer</h1><div class="note"><b>Aggregate human data only.</b> Empirical mode shows observed means; conditional mode shows a five-dimensional Ridge estimate. Sparse outcomes may have many suppressed cells (minimum N=10).</div><div class="grid"><label>X <select id="x"></select></label><label>Y <select id="y"></select></label><label>Outcome <select id="outcome"></select></label><label>Landscape <select id="mode"><option value="empirical">Observed / marginal</option><option value="conditional">Conditional 5D model</option></select></label><label>View <select id="view"><option value="3d">3D surface</option><option value="2d">2D heatmap</option></select></label></div><div id="sliders" class="panel"></div><div class="panel"><label><input type="checkbox" id="trend"> Trend plane</label><label><input type="checkbox" id="zero" checked> Zero / sample mean plane</label><span id="status"></span></div><div id="plot"></div><div class="small">The model is descriptive and cross-sectional. Zero is the selected outcome's sample mean, not a clinical threshold.</div><script>const B=__BUNDLE__,axes=B.axes,xs=document.getElementById('x'),ys=document.getElementById('y'),os=document.getElementById('outcome'),sl=document.getElementById('sliders'),status=document.getElementById('status'),vals={};axes.forEach(a=>{xs.add(new Option(a,a));ys.add(new Option(a,a));vals[a]=0});xs.value='Extraversion';ys.value='Emotional Stability';const cc={};B.grid.forEach(r=>cc[r.outcome]=(cc[r.outcome]||0)+1);Object.keys(B.outcomes).sort().forEach(o=>os.add(new Option(B.outcomes[o].label+' (N='+B.outcomes[o].N+', supported cells='+cc[o]+')',o)));os.value='content_balanced_ge2';function sliders(){sl.innerHTML='<b>Hidden-trait equalizer (conditional mode)</b>';axes.filter(a=>a!==xs.value&&a!==ys.value).forEach(a=>{const l=document.createElement('label');l.className='slider';l.textContent=a+' ';const i=document.createElement('input');i.type='range';i.min=-2.5;i.max=2.5;i.step=.05;i.value=vals[a];i.disabled=document.getElementById('mode').value!=='conditional';i.oninput=()=>{vals[a]=+i.value;draw()};l.append(i,document.createTextNode(' '+(+i.value).toFixed(2)+' SD'));sl.append(l)})}function draw(){sliders();const x=xs.value,y=ys.value,o=os.value,m=document.getElementById('mode').value,v=document.getElementById('view').value,rows=B.grid.filter(r=>r.outcome===o&&r.x===x&&r.y===y);if(!rows.length){status.textContent='No supported cells for this outcome/axis pair (N≥10).';Plotly.purge('plot');return}const c=B.coefficients[o],X=rows.map(r=>r.x_value),Y=rows.map(r=>r.y_value),Z=rows.map(r=>m==='empirical'?r.mean:c.intercept+c.coef[axes.indexOf(x)]*r.x_value+c.coef[axes.indexOf(y)]*r.y_value+axes.reduce((s,a,i)=>s+(a!==x&&a!==y?c.coef[i]*vals[a]:0),0)),ux=[...new Set(X)].sort((a,b)=>a-b),uy=[...new Set(Y)].sort((a,b)=>a-b),zm=uy.map(yy=>ux.map(xx=>{const i=rows.findIndex(r=>r.x_value===xx&&r.y_value===yy);return i<0?null:Z[i]})),tr=[v==='3d'?{x:ux,y:uy,z:zm,type:'surface',name:'Wellbeing',colorscale:'RdBu',cmin:-2,cmax:2}:{x:ux,y:uy,z:zm,type:'heatmap',name:'Wellbeing',colorscale:'RdBu',zmin:-2,zmax:2}];if(rows.length<25)tr.push(v==='3d'?{x:X,y:Y,z:Z,type:'scatter3d',mode:'markers',name:'Supported cells',marker:{size:5,color:Z,colorscale:'RdBu'}}:{x:X,y:Y,mode:'markers',name:'Supported cells',marker:{size:9,color:Z,colorscale:'RdBu'}});if(document.getElementById('zero').checked)tr.push(v==='3d'?{x:ux,y:uy,z:uy.map(()=>ux.map(()=>0)),type:'surface',name:'Zero / sample mean',opacity:.22,showscale:false,colorscale:[[0,'#777'],[1,'#777']]}:{x:ux,y:uy,z:uy.map(()=>ux.map(()=>0)),type:'contour',name:'Zero / sample mean',showscale:false,line:{color:'#777',dash:'dot'}});if(document.getElementById('trend').checked){const tz=uy.map(yy=>ux.map(xx=>c.intercept+c.coef[axes.indexOf(x)]*xx+c.coef[axes.indexOf(y)]*yy));tr.push(v==='3d'?{x:ux,y:uy,z:tz,type:'surface',name:'Trend plane',opacity:.35,showscale:false,colorscale:[[0,'#444'],[1,'#444']]}:{x:ux,y:uy,z:tz,type:'contour',name:'Trend plane',showscale:false,line:{color:'#333',dash:'dash'}})}Plotly.react('plot',tr,{title:(m==='conditional'?'Conditional 5D estimate':'Observed marginal mean')+' — '+o,xaxis:{title:x+' (standardized)'},yaxis:{title:y+' (standardized)'},scene:{xaxis:{title:x},yaxis:{title:y},zaxis:{title:o+' (centered)'}},margin:{l:50,r:20,t:50,b:45}},{responsive:true});status.textContent='N='+B.outcomes[o].N+' | supported cells='+cc[o]+' | '+(cc[o]<500?'Sparse outcome; suppressed regions remain blank.':'')+(m==='conditional'?' model-estimated slice':' observed sample average')}[xs,ys,os,document.getElementById('mode'),document.getElementById('view'),document.getElementById('trend'),document.getElementById('zero')].forEach(e=>e.addEventListener('change',draw));draw();</script></body></html>'''.replace('__BUNDLE__',json.dumps(data,separators=(',',':')))
(out/'sapa_wellbeing_terrain_explorer.html').write_text(html)
